class material { public: ~material(); };

template<class T> class vector {
public:
  T *begin;
  T *end;
  T *capacity;
  int size() const { return end - begin; }
  T&operator[](int i) { return begin[i]; }
};

struct material_map {
  void *header;
  int count;
  void *allocator;
  void clear();
};

struct stringx { unsigned char data[16]; };
struct bone { unsigned char data[80]; };

class visual_rep {
public:
  unsigned char base_data[16];
  virtual ~visual_rep();
};

extern reduced_face *global_n_tangle_reduced_faces;
extern wedge_ref *global_n_tangle_wedge_refs;
extern hw_rasta_vert *global_n_tangle_xverts_for_lod;
extern hw_rasta_vert *global_n_tangle_rasta_verts;
extern wedge *global_n_tangle_wedges;
extern face *global_n_tangle_faces;

class vr_pmesh : public visual_rep {
public:
  virtual ~vr_pmesh();
protected:
  vector<vert> *verts;
  hw_rasta_vert *xverts;
  wedge *wedges;
  int min_faces;
  int *xverts_for_lod;
  int num_wedges;
  face *faces;
  reduced_face *reduced_faces;
  int num_faces;
  vector<material*> materials;
  vert_ref *vert_refs_for_wedge_ref;
  wedge_ref *wedge_index_list;
  short *wedge_lod_starts;
  face_ref *original_face_for_face_slot;
  material_map material_changes;
  vector<bone> bones;
  unsigned char rest[44];
  stringx filename;
};

vr_pmesh::~vr_pmesh()
{
  if (reduced_faces && reduced_faces != global_n_tangle_reduced_faces)
    delete[] reduced_faces;
